    {

           using var activity =  StartCallActivity("SetChatThemeAsync", typeof(SetChatTheme).FullName ?? "SetChatThemeAsync");

           try
           {
             return client.SetChatThemeAsync(chatId, theme);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
